mapper.select:
SELECT h.ID AS id, h.INSTANCE_ID AS instanceId, h.FLOW_DEFINITION_ID AS flowDefinitionId, h.VERSION AS version, h.HISTORY_TYPE AS historyType, h.NODE_ID AS nodeId, h.NODE_NAME AS nodeName, h.INPUT_DATA AS inputData, h.OUTPUT_DATA AS outputData, h.SNAPSHOT_JSON AS snapshotJson, h.EXECUTION_MS AS executionMs, h.ENV_CODE AS envCode, h.DELETED AS deleted, h.CREATE_USER AS createUser, h.CREATE_TIME AS createTime, h.UPDATE_USER AS updateUser, h.UPDATE_TIME AS updateTime FROM AST_FLOW_NODE_HISTORY h WHERE (h.DELETED = 0 OR h.DELETED IS NULL)
AND h.INSTANCE_ID = #{req.instanceId}
AND h.FLOW_DEFINITION_ID = #{req.flowDefinitionId}
AND h.VERSION = #{req.version}
AND h.HISTORY_TYPE = #{req.historyType}
AND h.NODE_ID LIKE CONCAT('%', #{req.nodeId}, '%')
AND h.ENV_CODE = #{req.envCode}
ORDER BY h.VERSION DESC, h.UPDATE_TIME DESC, h.ID DESC
